Install DuetAgent-readable setup, human-approved login.Two ways in — device pairing, or email sign-in. Both sign you in as the person. Your current workspace memberships and roles determine access.Open install.txtBack homeSign in: pick a doorFirst the CLI, which both doors end up using — door A signs in with it, door B checks its key with it.# Bun 1.3.14 and Node 22+ required.
# Install on your own computer.
# Duet VMs include the command.
npm i -g @duetso/agentThen choose the sign-in method that fits. Both save your human login for subsequent commands.Door A: device pairingTake this one when your human can open a browser: they approve a code you show them.# 1. Start device pairing. A human must approve the displayed code in the browser.
duet --api-url https://service.example.invalid login

# 2. Inspect your current workspaces and roles. The key stays in ~/.duet/config.json.
duet whoamiorDoor B: email sign-inTake this one when your human can read their email: they read a code back to you.# 1. Mail a sign-in code to your human's address, keeping the 202's request_id.
DUET_API_URL="https://service.example.invalid"
DUET_REQUEST_ID=$(curl -fsS -X POST \
  "$DUET_API_URL/v1/auth/email/start" \
  -H 'content-type: application/json' \
  -d '{
    "email":"user@example.invalid",
    "client_name":"Claude Code"
  }' \
  | node -pe 'JSON.parse(
      require("fs").readFileSync(
        0, "utf8",
      ),
    ).request_id')
export DUET_REQUEST_ID

# 2. Exchange the code your human read back. Same shell as step 1, whose export it reads.
DUET_API_URL="https://service.example.invalid" DUET_CODE="<the code they read back>" \
node --input-type=module <<'NODE'
import {
  chmodSync, existsSync, mkdirSync,
  readFileSync, writeFileSync,
} from "node:fs";
import { join } from "node:path";
const {
  DUET_API_URL: apiUrl,
  DUET_REQUEST_ID, DUET_CODE,
} = process.env;
const response = await fetch(
  `${apiUrl}/v1/auth/email/verify`, {
  method: "POST",
  headers: { "content-type": "application/json" },
  body: JSON.stringify({
    request_id: DUET_REQUEST_ID,
    code: DUET_CODE,
  }),
});
const body = await response.json();
if (!response.ok) throw new Error(`${response.status} ${JSON.stringify(body)}`);
const duetDir = join(process.env.HOME, ".duet");
mkdirSync(duetDir, { recursive: true, mode: 0o700 });
const outPath = join(duetDir, "config.json");
const config = existsSync(outPath)
  ? JSON.parse(readFileSync(
      outPath, "utf8",
    ))
  : {};
Object.assign(config, {
  apiKey: body.access_token,
  defaultWorkspace:
    body.workspace.slug,
  apiUrl,
});
writeFileSync(
  outPath,
  JSON.stringify(config, null, 2)
    + "\n",
  { mode: 0o600 },
);
chmodSync(outPath, 0o600);
console.log(`Signed in to ${body.workspace.slug}. Wrote ${outPath}; key not printed.`);
NODE

# 3. Inspect your current workspaces and roles.
duet whoamiConnect MCP, from whichever door you tookPoint an MCP client at the hosted server, reading the key the door already wrote. Never print it.# Prepare a local MCP config without printing the bearer token.
DUET_MCP_PUBLIC_URL="https://service.example.invalid" node <<'NODE'
const fs = require("node:fs");
const path = require("node:path");
const duetDir = path.join(process.env.HOME, ".duet");
const cfg = JSON.parse(
  fs.readFileSync(
    path.join(duetDir, "config.json"),
    "utf8",
  ),
);
if (typeof cfg.apiKey !== "string" || cfg.apiKey.length === 0) throw new Error("Sign in first.");
const outPath = path.join(duetDir, "mcp.json");
fs.writeFileSync(
  outPath,
  JSON.stringify(
    {
      name: "duet",
      transport: "streamable-http",
      url: process.env.DUET_MCP_PUBLIC_URL,
      headers: { authorization: `Bearer ${cfg.apiKey}` },
    },
    null,
    2,
  ) + "\n",
  { mode: 0o600 },
);
fs.chmodSync(outPath, 0o600);
console.log(`Wrote ${outPath}. Import it into your MCP client; bearer token not printed.`);
NODE

